// -----------------------------------------------------------------------------
// Normalize LogEvent
//
// Accepts:
//   • Legacy ESP32 syslog messages
//   • Canonical LogEvent objects (future)
//
// Produces:
//   • Canonical LogEvent
// -----------------------------------------------------------------------------

const g_createLogEventObject = global.get('g_createLogEventObject');

// Future:
// if (isLogEvent(msg.payload)) {
//     return msg;
// }

// -----------------------------------------------------------------------------
// Legacy ESP32 Translation
// -----------------------------------------------------------------------------

/**
 * Determine whether the incoming payload is a log file (multiple legacy log
 * events concatenated together) rather than a single legacy log event.
 *
 * Assumption:
 * Each legacy log event generated by the ESP32 logging framework contains
 * exactly one "Line#:" field. Therefore, if the payload contains more than
 * one "Line#:", it is considered a log file replay.
 *
 * Returns:
 *   true  - Payload contains multiple legacy log events.
 *   false - Payload contains a single legacy log event.
 */

/*-----  IS THIS A LOG FILE COMING IN OR AN INDIVIDUAL ENTRY  -----*/

function isLogFile() {
    if (typeof msg.payload !== "string") return false;
    const matches = msg.payload.match(/Line#:/g);
    if (!matches) {
        return false;
    }
    return matches.length > 1;
}

/**
 * Normalize a legacy log file.
 *
 * A legacy log file consists of one or more legacy log events.
 * Each legacy log event is terminated by a '\n' character.
 */

/*-----  SPLIT THE LOG FILE INTO INDIVIDUAL ETRIES AND LET normalizeLegacyLogEvent DEAL WITH WHAT TO DO WITH THEM  -----*/

function normalizeLogFile() {

    const entries = msg.payload.split('\n');

    for (const entry of entries) {

        if (entry.length === 0) {
            continue;
        }

        const outMsg = {
            topic: msg.topic,
            payload: entry
        };

        normalizeLegacyLogEvent(outMsg);
    }
}
/*-----  IF THE EVENT ARRIVES AS AN OBJECT WITH THE CORRECTLY NAMES ELEMENTS  -----*/

function isCanonicalLogEvent() {
    if (typeof msg.payload !== "object" || msg.payload === null)
        return false;

    return (
        msg.payload.hasOwnProperty("eventTime") &&
        msg.payload.hasOwnProperty("component") &&
        msg.payload.hasOwnProperty("function") &&
        msg.payload.hasOwnProperty("message")
    );
}

/*-----  TRANSITION THE INCOMING LOG OBJECT TO THE STANDARD V2 LOGING OBJECT  -----*/

function normalizeCanonicalLogEvent() {

    // Create a new canonical LogEvent.
    const logEvent = g_createLogEventObject();
//    const logEvent = JSON.parse(JSON.stringify(config.logEventTemplate));

    // Copy only recognized fields.
    logEvent.eventTime = msg.payload.eventTime;
    logEvent.component = msg.payload.component;
    logEvent.function = msg.payload.function;
    logEvent.message = msg.payload.message;

    // Ensure data is always an object.
    if ("data" in msg.payload && typeof msg.payload.data === "object") {
        logEvent.data = msg.payload.data;
    }

    const outMsg = {
        payload: logEvent
    };

    node.send(outMsg);
    return;
}

/*-----  IS MSG.PAYLOAD A SINGLE LEGACY LOG ENTRY  -----*/

function isLegacyLogEvent() {
    if (typeof msg.payload !== "string") return false;
    const matches = msg.payload.match(/Line#:/g);
    if (!matches) {
        return false;
    }
    return matches.length === 1;
}

/*-----  NORMALIZE THE LEGACY EVENT TO THE V2 logEventTemplate  -----*/

function normalizeLegacyLogEvent(msg) {
    const logEvent = g_createLogEventObject();
//    const logEvent = JSON.parse(JSON.stringify(config.logEventTemplate));
    const outMsg = {};

    //outMsg.originalPayload = outMsg.payload;

    // Determine the component from the MQTT topic.
    const topicParts = msg.topic.split("/");
    logEvent.component = topicParts[0];

    // Save the original payload while translating.
    const text = msg.payload;

    // Find the first two commas.
    const firstComma = text.indexOf(",");
    const secondComma = text.indexOf(",", firstComma + 1);

    // Event Time
    logEvent.eventTime = text.substring(0, firstComma).trim();

    // Line Number
    const lineText = text.substring(firstComma + 1, secondComma).trim();
    logEvent.line = Number(lineText.replace("Line#:", ""));

    // Remaining text (Stage 2 will parse this)
    logEvent.data.originalPayload = text;

    // Parse the FROM field.
    const fromText = text.substring(secondComma + 1).trim();

    // Remove the "FROM:" prefix.
    const functionText = fromText.replace("FROM:", "").trim();

    // Find the separator between the function name and the message.
    const separator = functionText.indexOf(":");

    // Function name.
    logEvent.function = functionText.substring(0, separator).trim();

    // Log message.
    logEvent.message = functionText.substring(separator + 1).trim();

    outMsg.payload = logEvent;

    node.send(outMsg);
}

/*-----  MAIN  -----*/

if (isCanonicalLogEvent())
    normalizeCanonicalLogEvent();

else if (isLogFile())
    normalizeLogFile();

else if (isLegacyLogEvent())
    normalizeLegacyLogEvent(msg);

else {
    node.error(
        "Normalize LogEvent: Unsupported log event format. Payload type: " +
        typeof msg.payload +
        ", Payload: " +
        JSON.stringify(msg.payload)
    );    return null;
}
return null;


/*
Rule 1
If msg.payload is an object that satisfies the minimum LogEvent contract, then it is a Canonical LogEvent.
Canonical Object
      │
      ▼
normalizeCanonicalLogEvent()

Rule 2
If msg.payload is a string containing more than one Line#:, then it is a Log File.
Legacy Log File
      │
      ▼
normalizeLogFile()

Rule 3
If msg.payload is a string containing exactly one Line#:, then it is a Legacy Log Event.
Legacy Log Event
      │
      ▼
normalizeLegacyLogEvent()


Everything else is unsupported.
Unsupported
      │
      ▼
node.error(...)
return;
*/
